Motivation
Biplots can contain a lot of information. In a previous post called Drawing an interactive biplot with echarts4r we saw how to move from a static biplot, drawn with biplotEZ, to an interactive biplot, drawn with echarts4r.
Still, those of you with a keen eye would have seen that two of the variables were illustrated essentially on top of one another. In an interactive plot it is sometimes possible to still separate them visually but this is a general problem that occurs when drawing biplots.
Ideally, biplots should be drawn deliberately one at a time, with care and attention to data preparation. However, practically one often might need to draw many biplots in a loop and the hope is to have them come out as interpretable automatically.
When drawing multiple biplots as part of an automated, looping, or otherwise recurring, process it is important to have a robust pipeline.


Robust solution: plot with accompanying tables
Normally the goal with a biplot is to place a lot of information on a single figure. However, a single figure can only hold so much information, and when that information overlaps on the figure then there is not a lot we can do.
If we allow for additional information to accompany the figure then there is much that can be done to improve on the figure itself.
I envision two additional steps:

Pre-processing of input data for severe data problems,
Post-processing of PCA output to avoid visual problems,

with the results of these combined into a small table to accompany the biplot.


Code
data_check &lt;- function(df, threshold = 0.97, display_issues = TRUE) {
  if (!any(class(df) %in% "data.frame")) {df &lt;- as.data.frame(df)}
  varnames &lt;- names(df)
  num_vars &lt;- seq_len(ncol(df)) |&gt; sapply(\(j) {
    isnum &lt;- is.numeric(df[[j]])
  })
  valid_vars &lt;- seq_len(ncol(df)) |&gt; sapply(\(j) {
    if (num_vars[j]) {
      sd(df[[j]]) &gt; 0
    } else {
      FALSE
    }
  })
  degenerate &lt;- num_vars & !valid_vars
  if (any(degenerate)) {
    degen_df &lt;&lt;- data.frame(Name = varnames[degenerate], 
                            Number = which(degenerate), 
                            Problem = "Degenerate"
                           )
    if (display_issues) {
      cat("\n\nThe following variables have no variation to model:\n\n")
      degen_df |&gt; knitr::kable() |&gt; print()
      cat("\n\n")
    }
  }
  numv &lt;- which(valid_vars)
  num_df &lt;- df[,valid_vars]
  p &lt;- ncol(num_df)
  abscormat &lt;- abs(cor(num_df) - diag(p))
  colinear_df &lt;&lt;- seq(1, p - 1) |&gt; lapply(\(i) {
    seq(i + 1, p) |&gt; lapply(\(j) {
      if (abscormat[i,j] &gt; threshold) {
        m &lt;- lm(df[[numv[j]]] ~ df[[numv[i]]]) |&gt; coef()
        data.frame(Num1 = numv[i], Num2 = numv[j], 
                   Var1 = varnames[numv[i]], 
                   Var2 = varnames[numv[j]], 
                   Corr = abscormat[i,j],
                   Formula = paste0(
          varnames[numv[j]], " ≈ ", round(m[2], 3), "*", varnames[numv[i]], 
          " + ", round(m[1], 3)))
      }
    }) |&gt; do.call(rbind, args = _)
  }) |&gt; do.call(rbind, args = _)
  if (display_issues && !is.null(colinear_df)) {
    cat("\n\nThe following variables have severe colinearity:\n\n")
    colinear_df[,3:6] |&gt; knitr::kable() |&gt; print()
    cat("\n\n")
  }
  all_fine &lt;- !degenerate
  if (!is.null(colinear_df)) {all_fine[colinear_df$Num1] &lt;- FALSE}
  df[, all_fine]
}

missing_check &lt;- function(df, threshold = 0.5, display_issues = TRUE) {
  empty_vars &lt;- seq_len(ncol(df)) |&gt; sapply(\(j) {
    mean(is.na(df[[j]])) &gt; threshold
  })
  if (display_issues & any(empty_vars)) {
    cat("\n\nVariables dropped for containing too few non-missing values:\n\n", 
        paste(names(df)[empty_vars], collapse = ", "), ".", sep = "")
  }
  df &lt;- df[, !empty_vars]
  num_vars &lt;- seq_len(ncol(df)) |&gt; sapply(\(j) {
    isnum &lt;- is.numeric(df[[j]])
  })
  problem_rows &lt;- seq_len(nrow(df)) |&gt; sapply(\(r) {
    any(is.na(df[r, num_vars]))
  })
  if (display_issues & any(problem_rows)) {
    cat("\n\nRows dropped for containing missing values:\n\n", 
        paste(which(problem_rows), collapse = ", "), ".", sep = "")
  }
  df[!problem_rows, ]
}

good_angles &lt;- function(bp, threshold = 0.07, display_issues = TRUE) {
  angles &lt;- atan2(bp$ax.one.unit[,2], bp$ax.one.unit[,1]) %% pi
  dist_df &lt;- rbind(data.frame(Varnum = 1, Fine = TRUE, Closest = 1), 
    seq(2, length(angles)) |&gt; lapply(\(i) {
    difs &lt;- abs(angles[seq_len(i-1)] - angles[i])
    data.frame(
      Varnum = i, 
      Fine = all(difs &gt; threshold), 
      Closest = which.min(difs)
    )
  }) |&gt; do.call(rbind, args = _))
  bp$axes_angles &lt;- dist_df
  if (!all(dist_df$Fine)) {
    issues_df &lt;- dist_df |&gt; subset(!Fine)
    issues_df$Closest_varname &lt;- bp$axes$names[issues_df$Closest]
    varnames &lt;- colnames(bp$X)
    issues_df$Formula &lt;- seq_len(nrow(issues_df)) |&gt; sapply(\(j) {
      m &lt;- lm(bp$X[,issues_df$Varnum[j]] ~ bp$X[,issues_df$Closest[j]]) |&gt; 
        coef()
      paste0(varnames[issues_df$Varnum[j]], " ≈ ", round(m[2], 3), 
             "*", varnames[issues_df$Closest[j]], 
            " + ", round(m[1], 3))
    })
    if (display_issues) {
      issues_df |&gt; kable() |&gt; print()
    }
    bp$angle_issues_df &lt;- issues_df
  }
  bp$good_angles &lt;- dist_df$Fine |&gt; which()
  bp
}

robust_biplot &lt;- function(df, group_col = 1, compile_issues = TRUE) {
  clean_df &lt;- df |&gt; missing_check(display_issues = FALSE) |&gt; 
    data_check(display_issues = FALSE)
  bp_obj &lt;- clean_df |&gt; biplot(classes = clean_df[[group_col]],
                               scaled = TRUE) |&gt; PCA() |&gt; 
    good_angles(display_issues = FALSE)
  prop_explained &lt;- bp_obj$eigenvalues[1:2]/sum(bp_obj$eigenvalues)
  p_expl &lt;- round(prop_explained*100)
  plt &lt;- bp_obj |&gt; 
    axes(which = bp_obj$good_angles) |&gt; 
    plot()
  if (compile_issues) {
    tryCatch({
      cat("\n\n")
      degen_df |&gt; kable() |&gt; print()
    }, error = \(e) NULL)
    tryCatch({
      cat("\n\n")
      colinear_df |&gt; kable() |&gt; print()
    }, error = \(e) NULL)
    tryCatch({
      cat("\n\n")
      bp_obj$angle_issues_df |&gt; kable() |&gt; print()
    }, error = \(e) NULL)
  }
  # library(ggplot2)
  # plt + labs(x = paste0("PCA (", p_expl[1], "%)"), 
  #                    y = paste0("PCA (", p_expl[2], "%)"))
  bp_obj |&gt; invisible()
}




